 function makeBall(x=0,z=0,vx=0,vz=0){const group=new THREE.Group();const core=new THREE.Mesh(new THREE.SphereGeometry(BALL_R,22,16),ballMat);core.castShadow=true;group.add(core);const halo=new THREE.Mesh(new THREE.SphereGeometry(.42,20,16),new THREE.MeshBasicMaterial({color:'#63ffe8',transparent:true,opacity:.09,depthWrite:false}));group.add(halo);const trailMat=new THREE.MeshBasicMaterial({color:'#75fff0',transparent:true,opacity:.2});const trail=new THREE.Mesh(new THREE.SphereGeometry(.11,12,8),trailMat);trail.scale.set(1,1,2.4);group.add(trail);group.position.set(x,.48,z);scene.add(group);let v=new THREE.Vector2(vx,vz);if(v.length()<.1){let candidates=players.filter(p=>p.active);let p=candidates[Math.floor(Math.random()*candidates.length)]||players[0];let tx=0,tz=0;switch(p.id){case 0:tz=1;break;case 1:tx=-1;break;case 2:tz=-1;break;case 3:tx=1;break}const sideOffset=(Math.random()-.5)*.8;v.set(tx+sideOffset,tz+(Math.abs(tx)>.2?sideOffset:0)).normalize().multiplyScalar(baseSpeed)}balls.push({group,vel:v,spin:Math.random()*6.2,boost:1})}
