const heartIcons=[...document.querySelectorAll('.hearts')];
function updateHud(){players.forEach(p=>{p.card.classList.toggle('out',!p.active);[...p.card.querySelectorAll('.heart')].forEach((el,i)=>el.classList.toggle('off',i>=p.life));if(!p.active)p.card.querySelector('.card-bottom').textContent='ELIMINADO'});document.querySelector('#ballCount').textContent=`${balls.length} ${balls.length===1?'PELOTA':'PELOTAS'}`;document.querySelector('#eventTimer').textContent=Math.max(0,eventLeft).toFixed(1);document.querySelector('#round').textContent=`${String(Math.floor(elapsed/60)+1).padStart(2,'0')} · ${String(Math.floor(elapsed%60)).padStart(2,'0')}`}
function showToast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),1450)}
function beep(freq=520,dur=.08){if(!soundOn)return;try{ac??=new AudioContext();const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+dur);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+dur)}catch{}}
const modal=document.querySelector('#overlay'),title=document.querySelector('#modalTitle'),copy=document.querySelector('#modalCopy'),eyebrow=document.querySelector('#eyebrow'),playBtn=document.querySelector('#playBtn');
function showModal(type){paused=true;modal.classList.remove('hidden');if(type==='start'){eyebrow.textContent='UNA ARENA · CUATRO RIVALES';title.textContent='¿Sobrevivirás?';copy.textContent='Desliza para mover tu nave. Devuelve la esfera y sobrevive a los otros tres pilotos.';playBtn.textContent='EMPEZAR PARTIDA'}else if(type==='pause'){eyebrow.textContent='PAUSA TÁCTICA';title.textContent='Respira, piloto';copy.textContent='La arena espera. Cuando estés listo, vuelve a defender tu lado.';playBtn.textContent='VOLVER A LA ARENA'}else{const won=type==='win';eyebrow.textContent=won?'ÚLTIMO PILOTO EN PIE':'NAVE DESTRUIDA';title.textContent=won?'¡La arena es tuya!':'Fin de la partida';copy.textContent=won?'Has superado a los tres rivales. ¿Una ronda más?':'Te quedaste sin vidas. Ajusta tu posición y vuelve a intentarlo.';playBtn.textContent='JUGAR DE NUEVO'}}
function resetGame(){for(const b of balls)scene.remove(b.group);balls.length=0;players.forEach(p=>{p.life=3;p.active=true;p.pos=0;p.target=0;p.hitCooldown=0;p.card.classList.remove('out')});gates.forEach(g=>g.visible=false);elapsed=0;eventLeft=10;lifeFree=0;totalRound++;ended=false;paused=false;input.x=0;setKnob(0);startBall();updateHud();modal.classList.add('hidden');showToast('¡A LA ARENA!')}
playBtn.addEventListener('click',()=>{if(title.textContent==='Respira, piloto'){paused=false;modal.classList.add('hidden')}else resetGame()});
document.querySelector('#pauseBtn').addEventListener('click',()=>{if(ended)return;if(paused&&modal.classList.contains('hidden'))return;if(!paused)showModal('pause');else if(title.textContent==='Respira, piloto'){paused=false;modal.classList.add('hidden')}});
document.querySelector('#soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.style.color=soundOn?'#61f2df':'';if(soundOn){ac??=new AudioContext();beep(680)}});
function setKnob(v){const knob=document.querySelector('#knob');knob.style.left=`${50+v*39}%`}
const slider=document.querySelector('#slider');let sliding=false;function pointerMove(e){const r=slider.getBoundingClientRect();const v=Math.max(-1,Math.min(1,((e.clientX-r.left)/r.width-.5)*2));input.x=v;setKnob(v)}slider.addEventListener('pointerdown',e=>{sliding=true;slider.setPointerCapture(e.pointerId);pointerMove(e)});slider.addEventListener('pointermove',e=>{if(sliding)pointerMove(e)});slider.addEventListener('pointerup',()=>{sliding=false});slider.addEventListener('pointercancel',()=>{sliding=false});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','a','A','d','D'].includes(e.key)){input.keys.add(e.key.toLowerCase());e.preventDefault()}if(e.key==='Escape'||e.key===' '){e.preventDefault();if(!paused&&!ended)showModal('pause');else if(paused&&title.textContent==='Respira, piloto'){paused=false;modal.classList.add('hidden')}}});window.addEventListener('keyup',e=>input.keys.delete(e.key.toLowerCase()));
function getInput(){let k=0;if(input.keys.has('a')||input.keys.has('arrowleft'))k-=1;if(input.keys.has('d')||input.keys.has('arrowright'))k+=1;return k||input.x}
function moveAI(dt){const activeBalls=balls;if(!activeBalls.length)return;for(const p of players){if(!p.active||p.id===0)continue;let best=null,bestScore=Infinity;for(const b of activeBalls){const x=b.group.position.x,z=b.group.position.z;const along=(p.id===1||p.id===3)?z:x;const toward=(p.id===1?b.vel.x:p.id===3?-b.vel.x:p.id===2?b.vel.z:-b.vel.z);const approaching=toward>.04;const score=Math.abs(along-p.pos)-(approaching?1.2:0);if(score<bestScore){bestScore=score;best=along}}if(best!==null){p.target=THREE.MathUtils.clamp(best,-7.7,7.7);const speed=2.2+Math.random()*.25;p.pos=THREE.MathUtils.damp(p.pos,p.target,speed,dt);placePlayer(p)}}}
function impactBall(ball,p){const q=ball.group.position;const px=p.group.position.x,pz=p.group.position.z;let dx=q.x-px,dz=q.z-pz;let dist=Math.hypot(dx,dz);const min=SHIP_R+BALL_R;if(dist>=min||p.hitCooldown>0)return false;if(dist<.001){dx=p.id===1?1:p.id===3?-1:0;dz=p.id===0?-1:p.id===2?1:0;dist=1}dx/=dist;dz/=dist;const dot=ball.vel.x*dx+ball.vel.y*dz;if(dot<0){ball.vel.x-=2*dot*dx;ball.vel.y-=2*dot*dz}else{ball.vel.x+=dx*1.6;ball.vel.y+=dz*1.6}const move= p.id===0?getInput():Math.sign(p.target-p.pos);ball.vel.x+=move*.45;ball.vel.y+= (p.id===0?-1:p.id===2?1:0)*.24;const max=8.5;ball.vel.setLength(Math.min(max,Math.max(baseSpeed*.86,ball.vel.length())));q.x=px+dx*(min+.015);q.z=pz+dz*(min+.015);p.hitCooldown=.14;beep(430+Math.random()*180,.065);return true}
function sideOf(x,z){if(x>EDGE+.15)return 3;if(x<-EDGE-.15)return 1;if(z>EDGE+.15)return 0;if(z<-EDGE-.15)return 2;return -1}
function bounceEdge(ball,side){const p=players[side],q=ball.group.position;if(p.active){p.life--;p.hitCooldown=.6;eventLeft=10;lifeFree=0;showToast(p.id===0?'¡PERDISTE UNA VIDA!':`${names[p.id]} PIERDE UNA VIDA`);beep(170,.22);if(p.life<=0){p.active=false;gates[side].visible=true;showToast(p.id===0?'NAVE DESTRUIDA':`${names[p.id]} ELIMINADO`)}if(p.id===0){ended=true;showModal('lose');return true}if(players.filter(a=>a.active).length===1&&players[0].active){ended=true;showModal('win');return true}q.set(0,.48,0);let t=players.filter(a=>a.active);const target=t[Math.floor(Math.random()*t.length)]||players[0];let vx=(Math.random()-.5)*.8,vz=(Math.random()-.5)*.8;if(target.id===0)vz=1;if(target.id===1)vx=-1;if(target.id===2)vz=-1;if(target.id===3)vx=1;ball.vel.set(vx,vz).normalize().multiplyScalar(baseSpeed);return true}
// Eliminated side is sealed: reflect the sphere back into play.
if(side===0&&ball.vel.y>0||side===2&&ball.vel.y<0)ball.vel.y*=-1;if(side===1&&ball.vel.x<0||side===3&&ball.vel.x>0)ball.vel.x*=-1;q.x=THREE.MathUtils.clamp(q.x,-EDGE,EDGE);q.z=THREE.MathUtils.clamp(q.z,-EDGE,EDGE);beep(300,.06);return false}

